export const QUIZ_IMAGE_BY_ID: Record<string, QuizImage> = Object.fromEntries(
  QUIZ_IMAGES.map((i) => [i.id, i])
);

/**
 * Sökvägen till en bild. `stad:<id>` pekar på ett stadsfoto som redan finns i
 * public/cities/, så att en fråga om Eiffeltornet kan använda samma bild som
 * stadsskärmen i stället för att ladda ner den en gång till.
 */
export function quizImageUrl(id: string): string {
  if (id.startsWith('stad:')) return `./cities/${id.slice(5)}.jpg`;
  if (id.startsWith('stadsbild:')) return `./cities/${id.slice(10)}-stad.jpg`;
  return `./quiz/${id}.webp`;
}

/** Alt-texten för en bild, oavsett var den kommer ifrån. */
export function quizImageAlt(id: string, cityName?: string): string {
  if (id.startsWith('stad:')) return cityName ? `Foto från ${cityName}` : 'Stadsfoto';
  return QUIZ_IMAGE_BY_ID[id]?.alt ?? '';
}

/**
 * Alt-texten när bilden står i en fråga. Den vanliga texten namnger gärna
 * motivet ("Turning Torso i Malmö"), vilket är rätt i bildvalsspelen men
 * ger bort svaret för den som lyssnar på frågan. Här används i första hand
 * bildens `altFraga`, en beskrivning utan namn; saknas den, och den vanliga
 * texten innehåller något av svarsalternativen, blir det en neutral rad.
 */
export function quizImageAltIFraga(id: string, alternativ: string[], cityName?: string): string {
  if (id.startsWith('stadsbild:')) return cityName ? `Stadsbild från ${cityName}` : 'Stadsbild';
  if (id.startsWith('stad:')) return cityName ? `Foto från ${cityName}` : 'Stadsfoto';
  const bild = QUIZ_IMAGE_BY_ID[id];
  if (!bild) return '';
  if (bild.altFraga) return bild.altFraga;
  return altLacker(bild.alt, alternativ) ? 'Foto som hör till frågan' : bild.alt;
}

/** Sant om alt-texten innehåller något av svarsalternativen. */
export function altLacker(alt: string, alternativ: string[]): boolean {
  const l = alt.toLowerCase();
  const fly = (t: string) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return alternativ.some((a) => {
    const ord = a.toLowerCase().replace(/\s*\(.*\)\s*$/, '').trim();
    if (ord.length < 3) return false;
    // Hela ord: "rosa ros" ska inte fällas av alternativet "Ros", men
    // "turning torso" av "Turning Torso".
    return new RegExp(`(?<![\\p{L}])${fly(ord)}(?![\\p{L}])`, 'u').test(l);
  });
}
